import{_ as h,o as t,c,a2 as o}from"./chunks/framework.62rcL0wY.js";const d=JSON.parse('{"title":"Trình soạn thảo và kính lúp","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/trinh-soan-thao.md","filePath":"bat-dau/trinh-soan-thao.md"}'),i={name:"bat-dau/trinh-soan-thao.md"};function a(g,n,l,r,e,p){return t(),c("div",null,[...n[0]||(n[0]=[o('<h1 id="trinh-soan-thao-va-kinh-lup" tabindex="-1">Trình soạn thảo và kính lúp <a class="header-anchor" href="#trinh-soan-thao-va-kinh-lup" aria-label="Permalink to &quot;Trình soạn thảo và kính lúp&quot;">​</a></h1><p>Trang này hướng dẫn cách sử dụng cửa sổ trình soạn thảo script tích hợp của Clickermann, phím tắt chèn nhanh tọa độ/màu sắc và công cụ kính lúp màn hình.</p><div class="info custom-block"><p class="custom-block-title">Hình minh họa sẽ bổ sung</p><p>Hình chụp cửa sổ trình soạn thảo script (với 4 nhóm nút trên thanh công cụ, khung thông tin tọa độ/màu sắc/HWND theo thời gian thực và ô kính lúp ở góc dưới bên trái) sẽ được bổ sung sau khi chụp trực tiếp trên máy Windows.</p></div><h2 id="bo-cuc-thanh-cong-cu" tabindex="-1">Bố cục thanh công cụ <a class="header-anchor" href="#bo-cuc-thanh-cong-cu" aria-label="Permalink to &quot;Bố cục thanh công cụ&quot;">​</a></h2><p>Trình soạn thảo là nơi bạn dành phần lớn thời gian để viết và chỉnh sửa mã lệnh <code>.cms</code>. Cửa sổ được trang bị tô màu cú pháp, tự động căn lề và nhiều công cụ lấy thông số màn hình.</p><p>Các cụm nút chức năng trên trình soạn thảo được chia thành 4 nhóm chính:</p><ol><li><strong>Nhóm quản lý tệp script (hàng trên):</strong> Tạo mới, mở tệp, mở lịch sử các tệp gần đây, lưu (<code>Ctrl + S</code>) và lưu thành tệp mới.</li><li><strong>Nhóm công cụ hỗ trợ (hàng trên):</strong> Tìm kiếm và thay thế văn bản, bật/tắt <strong>kính lúp màn hình</strong>, tự động căn lề mã nguồn, v.v.</li><li><strong>Nhóm chèn nhanh mẫu lệnh (ở cột bên trái):</strong> Mở menu mẫu code và menu phân cấp để chèn nhanh lệnh vào trình soạn thảo. <ul><li>Các tệp mẫu nằm tại thư mục <code>%Clickermann%/data/lang/ru/templates/</code> (thay cho <code>ru</code> có thể là ngôn ngữ khác), bạn có thể tự sửa hoặc tạo mẫu mới.</li><li>Tệp menu phân cấp chèn lệnh nhanh nằm tại <code>%Clickermann%/data/lang/ru/qinsert_menu.txt</code>, bạn cũng có thể chỉnh sửa bằng trình soạn thảo văn bản thông thường (như Notepad) miễn là giữ đúng định dạng.</li></ul></li><li><strong>Nhóm điều khiển chạy script (ở cột bên trái, ngay bên dưới nhóm 3):</strong> Gồm các nút <strong>Áp dụng</strong>, <strong>Chạy</strong>, <strong>Dừng</strong> và <strong>Nhật ký</strong>. Ba nút cuối lặp lại chức năng của các nút tương ứng trên màn hình chính; riêng nút <strong>Áp dụng</strong> dùng để cập nhật nội dung đang hiển thị trong trình soạn thảo thành script làm việc hiện tại của chương trình.</li></ol><h2 id="khung-thong-tin-thoi-gian-thuc-va-phim-tat-alt-q" tabindex="-1">Khung thông tin thời gian thực và phím tắt <code>Alt + Q</code> <a class="header-anchor" href="#khung-thong-tin-thoi-gian-thuc-va-phim-tat-alt-q" aria-label="Permalink to &quot;Khung thông tin thời gian thực và phím tắt `Alt + Q`&quot;">​</a></h2><p>Ở cột bên trái (phía dưới các nút điều khiển), chương trình hiển thị liên tục theo thời gian thực các thông số tại vị trí con trỏ chuột hiện tại:</p><ul><li><p>Tọa độ con trỏ chuột <code>X</code>, <code>Y</code>.</p></li><li><p>Mã màu của điểm ảnh ngay dưới mũi trỏ chuột.</p></li><li><p>Mã định danh <code>HWND</code> của phần tử cửa sổ dưới trỏ chuột.</p></li><li><p><strong>Mẹo thao tác nhanh với <code>Alt + Q</code>:</strong> Nhấn tổ hợp phím <code>Alt + Q</code> (mặc định) để chèn nhanh tọa độ và màu sắc hiện tại vào script dưới dạng câu lệnh <code>LCLICK</code> để không phải gõ lại từng con số bằng tay; hoặc chỉ chép tọa độ hiện tại vào bộ nhớ tạm (Clipboard) khi bật chế độ tương ứng bằng nút có biểu tượng Clipboard.</p></li></ul><h2 id="kinh-lup-man-hinh-va-chup-nhanh-mau-anh-alt-g" tabindex="-1">Kính lúp màn hình và chụp nhanh mẫu ảnh <code>Alt + G</code> <a class="header-anchor" href="#kinh-lup-man-hinh-va-chup-nhanh-mau-anh-alt-g" aria-label="Permalink to &quot;Kính lúp màn hình và chụp nhanh mẫu ảnh `Alt + G`&quot;">​</a></h2><p>Ở góc dưới cùng bên trái của trình soạn thảo là <strong>kính lúp</strong> giúp phóng to vùng điểm ảnh quanh con trỏ chuột.</p><ul><li><strong>Hiển thị đúng như Clickermann nhìn thấy:</strong> Kính lúp hiển thị hình ảnh màn hình sau khi đã áp dụng chế độ giảm màu (<code>COLORMODE</code>) và chế độ khóa cửa sổ, giúp bạn kiểm tra chính xác những gì chương trình đang nhận diện.</li><li><strong>Bật / tắt kính lúp:</strong> Mặc định kính lúp được tắt để đỡ tốn tài nguyên CPU. Bạn bật kính lúp bằng nút có hình kính lúp trên thanh công cụ phía trên.</li><li><strong>Các nút dưới khung kính lúp (từ trái sang phải):</strong> Phóng to, thu nhỏ, đổi màu tâm ngắm và nút chuyển mức giảm màu (<code>0..7</code>). Lưu ý nút đổi mức giảm màu dưới kính lúp chỉ để xem thử bằng mắt, không tự thêm lệnh <code>COLORMODE</code> vào script.</li><li><strong>Giảm tốc độ chuột khi bật kính lúp:</strong> Khi kính lúp đang bật, tốc độ di chuyển chuột sẽ được làm chậm lại để bạn dễ căn chỉnh vào từng điểm ảnh. <strong>Hãy nhớ tắt kính lúp khi không dùng nữa hoặc trước khi đóng chương trình</strong> để tốc độ chuột trở lại bình thường.</li><li><strong>Chụp nhanh ảnh mẫu <code>100×100</code> bằng <code>Alt + G</code>:</strong> Nhấn <code>Alt + G</code> để chụp nhanh vùng ảnh <code>100×100</code> điểm ảnh mà kính lúp đang nhìn thấy; ảnh chụp tự động được áp dụng mức giảm màu hiện tại và lưu ở định dạng <code>.bmp</code>, bạn chỉ cần mở trong Paint để cắt gọn phần cần dùng.</li></ul><h2 id="khung-soan-thao-van-ban" tabindex="-1">Khung soạn thảo văn bản <a class="header-anchor" href="#khung-soan-thao-van-ban" aria-label="Permalink to &quot;Khung soạn thảo văn bản&quot;">​</a></h2><p>Toàn bộ phần bên phải là khung soạn thảo văn bản chuẩn. Bạn có thể dùng các phím tắt quen thuộc như:</p><ul><li><code>Ctrl + S</code>: Lưu nhanh tệp script.</li><li><code>Tab</code> / <code>Shift + Tab</code>: Thụt lề vào hoặc lùi lề ra cho cả khối dòng đang bôi đen.</li></ul><hr><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (bài Trình soạn thảo).</em></p>',18)])])}const m=h(i,[["render",a]]);export{d as __pageData,m as default};
